SELECT COUNT(1)
FROM clean_task ct
WHERE ct.camp_id = #{campId}
  AND ct.task_status IN ('pending', 'processing')

  AND ct.poi_id = #{poiId}


  AND DATE(ct.deadline_at) = #{businessDate}

SELECT COUNT(1)
FROM clean_task ct
WHERE ct.camp_id = #{campId}
  AND ct.task_status = 'pending'

  AND ct.poi_id = #{poiId}


  AND DATE(ct.deadline_at) = #{businessDate}

SELECT COUNT(1)
FROM clean_task ct
WHERE ct.camp_id = #{campId}
  AND ct.task_status IN ('pending', 'processing')
  AND ct.deadline_at IS NOT NULL
  AND HOUR(ct.deadline_at) >= #{startHour}
  AND HOUR(ct.deadline_at) < #{endHour}

  AND ct.poi_id = #{poiId}


  AND DATE(ct.deadline_at) = #{businessDate}
